-- Bootstrap 10 (tracker C7). Objects created by hand on the hosted production database and needed from 20261002210000_content_market_enforcement.sql on.
-- Each is created ONLY IF MISSING: on production nothing changes; on an empty database this supplies them. Generated by scripts/release/build_bootstrap.py.
begin;
set local check_function_bodies = off;

create table if not exists public.question_bank_items (
  id uuid default gen_random_uuid() not null,
  bank_id uuid not null,
  question_id uuid not null,
  display_order integer,
  added_by uuid,
  added_at timestamp with time zone default now() not null,
  PRIMARY KEY (id)
);
do $boot$ begin if to_regprocedure('public.qb_add_team_member(uuid, uuid, text)') is null then execute $qb_bootstrap$
CREATE OR REPLACE FUNCTION public.qb_add_team_member(p_team_id uuid, p_student_id uuid, p_role text DEFAULT 'MEMBER'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_team public.competition_teams%rowtype;
    v_member_id uuid;
begin if not quizbox_market.team_allowed(p_team_id) then raise exception 'QB_COMPETITION_CONTEXT_DENIED' using errcode='42501'; end if;

    select *
    into v_team
    from public.competition_teams
    where id = p_team_id;


    if not found then
        raise exception 'QB_COMPETITION_TEAM_NOT_FOUND';
    end if;


    if not (
        public.qb_can_manage_institution(
            v_team.institution_id
        )
        or public.qb_has_permission(
            'COMPETITION_MANAGE'
        )
        or public.qb_is_platform_admin()
    ) then
        raise exception 'QB_PERMISSION_DENIED';
    end if;


    if not exists (
        select 1
        from public.student_profiles
        where id = p_student_id
    ) then
        raise exception 'QB_STUDENT_NOT_FOUND';
    end if;


    insert into public.competition_team_members(
        team_id,
        student_id,
        role,
        roster_status
    )
    values(
        p_team_id,
        p_student_id,
        upper(coalesce(p_role,'MEMBER')),
        'PENDING'
    )

    on conflict(
        team_id,
        student_id
    )
    do update
    set
        role =
            excluded.role

    returning id
    into v_member_id;


    return jsonb_build_object(
        'status','PASS',
        'team_member_id',v_member_id,
        'roster_status','PENDING'
    );

end;
$function$
$qb_bootstrap$; end if; end $boot$;
do $boot$ begin if to_regprocedure('public.qb_attach_competition_sponsor(uuid, uuid, text, numeric, text)') is null then execute $qb_bootstrap$
CREATE OR REPLACE FUNCTION public.qb_attach_competition_sponsor(p_competition_id uuid, p_sponsor_id uuid, p_sponsorship_role text DEFAULT 'SPONSOR'::text, p_committed_amount numeric DEFAULT NULL::numeric, p_currency text DEFAULT 'GHS'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_id uuid;
begin if not quizbox_market.competition_allowed(p_competition_id) then raise exception 'QB_COMPETITION_CONTEXT_DENIED' using errcode='42501'; end if;

    if not (
        public.qb_has_permission(
            'COMPETITION_MANAGE'
        )
        or public.qb_is_platform_admin()
    ) then
        raise exception 'QB_PERMISSION_DENIED';
    end if;


    insert into public.competition_sponsors(
        competition_id,
        sponsor_id,
        sponsorship_role,
        committed_amount,
        currency,
        status
    )
    values(
        p_competition_id,
        p_sponsor_id,
        upper(
            coalesce(
                p_sponsorship_role,
                'SPONSOR'
            )
        ),
        p_committed_amount,
        upper(coalesce(p_currency,'GHS')),
        'ACTIVE'
    )

    on conflict(
        competition_id,
        sponsor_id,
        sponsorship_role
    )
    do update
    set
        committed_amount =
            excluded.committed_amount,

        currency =
            excluded.currency,

        status =
            'ACTIVE'

    returning id
    into v_id;


    return jsonb_build_object(
        'status','PASS',
        'competition_sponsor_id',v_id
    );

end;
$function$
$qb_bootstrap$; end if; end $boot$;
do $boot$ begin if to_regprocedure('public.qb_create_competition_team(uuid, uuid, text)') is null then execute $qb_bootstrap$
CREATE OR REPLACE FUNCTION public.qb_create_competition_team(p_competition_id uuid, p_institution_id uuid, p_team_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_team_id uuid;
    v_team_code text;
begin if not quizbox_market.competition_allowed(p_competition_id) then raise exception 'QB_COMPETITION_CONTEXT_DENIED' using errcode='42501'; end if;

    if not (
        public.qb_can_manage_institution(
            p_institution_id
        )
        or public.qb_has_permission(
            'COMPETITION_MANAGE'
        )
        or public.qb_is_platform_admin()
    ) then
        raise exception 'QB_PERMISSION_DENIED';
    end if;


    if nullif(trim(p_team_name),'') is null then
        raise exception 'QB_TEAM_NAME_REQUIRED';
    end if;


    if not exists (
        select 1
        from public.competition_institutions ci
        where ci.competition_id =
                p_competition_id
          and ci.institution_id =
                p_institution_id
    ) then
        raise exception
            'QB_SCHOOL_NOT_REGISTERED_FOR_COMPETITION';
    end if;


    v_team_code :=
        'TEAM-' ||
        upper(
            substr(
                replace(
                    gen_random_uuid()::text,
                    '-',
                    ''
                ),
                1,
                8
            )
        );


    insert into public.competition_teams(
        competition_id,
        institution_id,
        team_name,
        team_code,
        status
    )
    values(
        p_competition_id,
        p_institution_id,
        trim(p_team_name),
        v_team_code,
        'ACTIVE'
    )

    on conflict(
        competition_id,
        team_name
    )
    do update
    set
        institution_id =
            excluded.institution_id

    returning id
    into v_team_id;


    return jsonb_build_object(
        'status','PASS',
        'team_id',v_team_id,
        'team_code',v_team_code,
        'team_name',trim(p_team_name)
    );

end;
$function$
$qb_bootstrap$; end if; end $boot$;
do $boot$ begin if to_regprocedure('public.qb_finalize_competition_leaderboard(uuid)') is null then execute $qb_bootstrap$
CREATE OR REPLACE FUNCTION public.qb_finalize_competition_leaderboard(p_competition_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_updated integer := 0;
begin if not quizbox_market.competition_allowed(p_competition_id) then raise exception 'QB_COMPETITION_CONTEXT_DENIED' using errcode='42501'; end if;

    if not (
        public.qb_has_permission(
            'COMPETITION_MANAGE'
        )
        or public.qb_is_platform_admin()
    ) then
        raise exception 'QB_PERMISSION_DENIED';
    end if;


    with ranked as (

        select
            cr.id,

            dense_rank() over (
                order by
                    cr.score desc,
                    coalesce(
                        cr.percentage,
                        0
                    ) desc,
                    coalesce(
                        cr.completion_time_ms,
                        9223372036854775807
                    ) asc
            ) as new_rank

        from public.competition_results cr

        where cr.competition_id =
            p_competition_id

          and upper(cr.result_status) in (
              'FINAL',
              'PROVISIONAL'
          )
    )

    update public.competition_results cr

    set
        rank = ranked.new_rank,
        result_status = 'FINAL',
        calculated_at = now()

    from ranked

    where cr.id = ranked.id;


    get diagnostics v_updated =
        row_count;


    return jsonb_build_object(
        'status','PASS',
        'competition_id',p_competition_id,
        'ranked_results',v_updated
    );

end;
$function$
$qb_bootstrap$; end if; end $boot$;
do $boot$ begin if to_regprocedure('public.qb_record_competition_result(uuid, text, uuid, numeric, numeric, bigint, uuid, uuid, uuid, text)') is null then execute $qb_bootstrap$
CREATE OR REPLACE FUNCTION public.qb_record_competition_result(p_competition_id uuid, p_entity_type text, p_entity_id uuid, p_score numeric, p_percentage numeric DEFAULT NULL::numeric, p_completion_time_ms bigint DEFAULT NULL::bigint, p_stage_id uuid DEFAULT NULL::uuid, p_round_id uuid DEFAULT NULL::uuid, p_match_id uuid DEFAULT NULL::uuid, p_result_status text DEFAULT 'PROVISIONAL'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_result_id uuid;
begin if not quizbox_market.competition_allowed(p_competition_id) then raise exception 'QB_COMPETITION_CONTEXT_DENIED' using errcode='42501'; end if;

    if not (
        public.qb_has_permission(
            'COMPETITION_MANAGE'
        )
        or public.qb_is_platform_admin()
    ) then
        raise exception 'QB_PERMISSION_DENIED';
    end if;


    if upper(p_entity_type) not in (
        'STUDENT',
        'TEAM',
        'INSTITUTION'
    ) then
        raise exception
            'QB_INVALID_COMPETITION_ENTITY_TYPE';
    end if;


    /*
     * Update an existing result at the same competition
     * stage/round/match/entity position first.
     */

    select id
    into v_result_id
    from public.competition_results
    where competition_id = p_competition_id
      and entity_type = upper(p_entity_type)
      and entity_id = p_entity_id
      and stage_id is not distinct from p_stage_id
      and round_id is not distinct from p_round_id
      and match_id is not distinct from p_match_id
    limit 1;


    if v_result_id is null then

        insert into public.competition_results(
            competition_id,
            stage_id,
            round_id,
            match_id,

            entity_type,
            entity_id,

            score,
            percentage,
            completion_time_ms,

            result_status,
            calculated_at
        )
        values(
            p_competition_id,
            p_stage_id,
            p_round_id,
            p_match_id,

            upper(p_entity_type),
            p_entity_id,

            coalesce(p_score,0),
            p_percentage,
            p_completion_time_ms,

            upper(
                coalesce(
                    p_result_status,
                    'PROVISIONAL'
                )
            ),

            now()
        )
        returning id
        into v_result_id;

    else

        update public.competition_results
        set
            score =
                coalesce(p_score,0),

            percentage =
                p_percentage,

            completion_time_ms =
                p_completion_time_ms,

            result_status =
                upper(
                    coalesce(
                        p_result_status,
                        'PROVISIONAL'
                    )
                ),

            calculated_at =
                now()

        where id =
            v_result_id;

    end if;


    return jsonb_build_object(
        'status','PASS',
        'competition_result_id',v_result_id
    );

end;
$function$
$qb_bootstrap$; end if; end $boot$;
do $boot$ begin if to_regprocedure('public.qb_register_competition_school(uuid, uuid)') is null then execute $qb_bootstrap$
CREATE OR REPLACE FUNCTION public.qb_register_competition_school(p_competition_id uuid, p_institution_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_id uuid;
begin if not quizbox_market.competition_allowed(p_competition_id) then raise exception 'QB_COMPETITION_CONTEXT_DENIED' using errcode='42501'; end if;

    if not (
        public.qb_can_manage_institution(
            p_institution_id
        )
        or public.qb_has_permission(
            'COMPETITION_MANAGE'
        )
        or public.qb_is_platform_admin()
    ) then
        raise exception 'QB_PERMISSION_DENIED';
    end if;


    if not exists (
        select 1
        from public.competitions
        where id = p_competition_id
    ) then
        raise exception 'QB_COMPETITION_NOT_FOUND';
    end if;


    insert into public.competition_institutions(
        competition_id,
        institution_id,
        registration_status,
        verification_status,
        registered_at
    )
    values(
        p_competition_id,
        p_institution_id,
        'PENDING',
        'PENDING',
        now()
    )

    on conflict(
        competition_id,
        institution_id
    )
    do update
    set
        registration_status =
            excluded.registration_status

    returning id
    into v_id;


    return jsonb_build_object(
        'status','PASS',
        'competition_institution_id',v_id,
        'registration_status','PENDING'
    );

end;
$function$
$qb_bootstrap$; end if; end $boot$;
do $boot$ begin if to_regprocedure('public.qb_verify_team_member(uuid)') is null then execute $qb_bootstrap$
CREATE OR REPLACE FUNCTION public.qb_verify_team_member(p_team_member_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_team_id uuid;
    v_institution_id uuid;
begin if not exists(select 1 from public.competition_team_members m where m.id=p_team_member_id and quizbox_market.team_allowed(m.team_id)) then raise exception 'QB_COMPETITION_CONTEXT_DENIED' using errcode='42501'; end if;

    select
        ctm.team_id,
        ct.institution_id
    into
        v_team_id,
        v_institution_id
    from public.competition_team_members ctm
    join public.competition_teams ct
      on ct.id = ctm.team_id
    where ctm.id = p_team_member_id;


    if not found then
        raise exception 'QB_TEAM_MEMBER_NOT_FOUND';
    end if;


    if not (
        public.qb_can_manage_institution(
            v_institution_id
        )
        or public.qb_has_permission(
            'COMPETITION_MANAGE'
        )
        or public.qb_is_platform_admin()
    ) then
        raise exception 'QB_PERMISSION_DENIED';
    end if;


    update public.competition_team_members
    set
        roster_status = 'VERIFIED',
        verified_by = auth.uid(),
        verified_at = now()
    where id = p_team_member_id;


    return jsonb_build_object(
        'status','PASS',
        'team_member_id',p_team_member_id,
        'roster_status','VERIFIED'
    );

end;
$function$
$qb_bootstrap$; end if; end $boot$;

commit;
